  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→import { generateUUID } from '../utils/uuid';
 12→
 13→function generateId() {
 14→  return generateUUID();
 15→}
 16→
 17→export function AgentProvider({
 18→  children,
 19→  refreshTables,
 20→}: {
 21→  children: ReactNode;
 22→  refreshTables: () => Promise<void>;
 23→}) {
 24→  const userSessionId = useSessionId();
 25→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 26→  const [isStreaming, setIsStreaming] = useState(false);
 27→  const abortRef = useRef<AbortController | null>(null);
 28→  const textBufferRef = useRef('');
 29→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 30→  const assistantIdRef = useRef('');
 31→  const segmentsRef = useRef<ContentSegment[]>([]);
 32→  const currentTextRef = useRef('');
 33→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 34→  const sessionIdRef = useRef<string | null>(null);
 35→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 36→
 37→  const flushText = useCallback(() => {
 38→    const text = textBufferRef.current;
 39→    if (!text) return;
 40→    const id = assistantIdRef.current;
 41→    currentTextRef.current += text;
 42→    setMessages((prev) =>
 43→      prev.map((m) =>
 44→        m.id === id ? { ...m, content: m.content + text } : m
 45→      )
 46→    );
 47→    textBufferRef.current = '';
 48→  }, []);
 49→
 50→  const sendMessage = useCallback(
 51→    async (text: string) => {
 52→      if (isStreaming) return;
 53→
 54→      const userMsg: ChatMessage = {
 55→        id: generateId(),
 56→        role: 'user',
 57→        content: text,
 58→      };
 59→
 60→      const assistantId = generateId();
 61→      assistantIdRef.current = assistantId;
 62→      const assistantMsg: ChatMessage = {
 63→        id: assistantId,
 64→        role: 'assistant',
 65→        content: '',
 66→        toolCalls: [],
 67→        isStreaming: true,
 68→      };
 69→
 70→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 71→      setIsStreaming(true);
 72→      textBufferRef.current = '';
 73→      segmentsRef.current = [];
 74→      currentTextRef.current = '';
 75→      phaseRef.current = 'thinking';
 76→
 77→      // Build conversation history from current messages for resume fallback
 78→      const history = messages
 79→        .filter((m) => m.role === 'user' || m.role === 'assistant')
 80→        .map((m) => ({ role: m.role, content: m.content }));
 81→
 82→      // If there's pending history from a delete, start a new Langfuse session with that context
 83→      const pendingHistory = pendingHistoryRef.current;
 84→      pendingHistoryRef.current = null;
 85→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
 86→
 87→      const controller = new AbortController();
 88→      abortRef.current = controller;
 89→
 90→      // Extract all /skill-name references from message
 91→      let actualMessage = text;
 92→      let skills: string[] | undefined;
 93→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
 94→      if (slashMatches.length > 0) {
 95→        skills = slashMatches.map((m) => m[1]);
 96→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
 97→      }
 98→
 99→      await runAgentLoop(
100→        actualMessage,
101→        sessionIdRef.current,
102→        langfuseSessionId,
103→        pendingHistory ?? (history.length > 0 ? history : null),
104→        {
105→          onTextChunk: (chunk) => {
106→            textBufferRef.current += chunk;
107→            if (!flushTimerRef.current) {
108→              flushTimerRef.current = setTimeout(() => {
109→                flushText();
110→                flushTimerRef.current = null;
111→              }, 50);
112→            }
113→          },
114→          onThinkingDone: () => {
115→            // Extended thinking just ended and a text block is starting.
116→            // Create a thinking segment from accumulated thinking text.
117→            if (flushTimerRef.current) {
118→              clearTimeout(flushTimerRef.current);
119→              flushTimerRef.current = null;
120→            }
121→            flushText();
122→            if (currentTextRef.current.trim()) {
123→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
124→              currentTextRef.current = '';
125→            }
126→            phaseRef.current = 'answer';
127→            setMessages((prev) =>
128→              prev.map((m) =>
129→                m.id === assistantId
130→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
131→                  : m
132→              )
133→            );
134→          },
135→          onToolCall: (pending: ToolCallResult) => {
136→            if (flushTimerRef.current) {
137→              clearTimeout(flushTimerRef.current);
138→              flushTimerRef.current = null;
139→            }
140→            flushText();
141→            if (currentTextRef.current.trim()) {
142→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
143→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
144→              currentTextRef.current = '';
145→            }
146→            // Add a pending tool segment so the input is shown immediately
147→            segmentsRef.current.push({
148→              type: 'tool',
149→              toolResult: pending,
150→            });
151→            setMessages((prev) =>
152→              prev.map((m) =>
153→                m.id === assistantId
154→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
155→                  : m
156→              )
157→            );
158→          },
159→          onToolResult: (result: ToolCallResult) => {
160→            // Merge result into pending tool segment (keep input info, add output)
161→            const pendingIdx = segmentsRef.current.findIndex(
162→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
163→            );
164→            if (pendingIdx !== -1) {
165→              const pending = segmentsRef.current[pendingIdx].toolResult!;
166→              segmentsRef.current[pendingIdx] = {
167→                type: 'tool',
168→                toolResult: {
169→                  ...pending,
170→                  ...result,
171→                  sql: result.sql || pending.sql,
172→                  toolName: result.toolName || pending.toolName,
173→                  command: result.command || pending.command,
174→                  toolInput: result.toolInput || pending.toolInput,
175→                },
176→              };
177→            } else {
178→              segmentsRef.current.push({ type: 'tool', toolResult: result });
179→            }
180→            setMessages((prev) =>
181→              prev.map((m) =>
182→                m.id === assistantId
183→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
184→                  : m
185→              )
186→            );
187→            refreshTables();
188→            // When a skill is created, notify SkillsPanel to refresh
189→            if (result.toolName?.includes('create_skill')) {
190→              window.dispatchEvent(new CustomEvent('skills-updated'));
191→            }
192→          },
193→          onSubagentStart: (data) => {
194→            if (flushTimerRef.current) {
195→              clearTimeout(flushTimerRef.current);
196→              flushTimerRef.current = null;
197→            }
198→            flushText();
199→            if (currentTextRef.current.trim()) {
200→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
201→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
202→              currentTextRef.current = '';
203→            }
204→            segmentsRef.current.push({
205→              type: 'subagent_start',
206→              subagentId: data.id,
207→              subagentName: data.name,
208→              text: data.prompt,
209→            });
210→            setMessages((prev) =>
211→              prev.map((m) =>
212→                m.id === assistantId
213→                  ? { ...m, segments: [...segmentsRef.current] }
214→                  : m
215→              )
216→            );
217→          },
218→          onSubagentEnd: (data) => {
219→            segmentsRef.current.push({
220→              type: 'subagent_end',
221→              subagentId: data.id,
222→              subagentName: data.name,
223→              chart_spec: data.chart_spec,
224→              sqlResults: data.sql_results,
225→              text: data.result,
226→            });
227→            setMessages((prev) =>
228→              prev.map((m) =>
229→                m.id === assistantId
230→                  ? { ...m, segments: [...segmentsRef.current] }
231→                  : m
232→              )
233→            );
234→          },
235→          onDone: (newSessionId) => {
236→            if (newSessionId) sessionIdRef.current = newSessionId;
237→            if (flushTimerRef.current) {
238→              clearTimeout(flushTimerRef.current);
239→              flushTimerRef.current = null;
240→            }
241→            flushText();
242→            if (currentTextRef.current.trim()) {
243→              segmentsRef.current.push({
244→                type: 'answer',
245→                text: currentTextRef.current,
246→              });
247→              currentTextRef.current = '';
248→            }
249→            setMessages((prev) =>
250→              prev.map((m) =>
251→                m.id === assistantId
252→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
253→                  : m
254→              )
255→            );
256→            setIsStreaming(false);
257→            abortRef.current = null;
258→          },
259→          onError: (error) => {
260→            if (flushTimerRef.current) {
261→              clearTimeout(flushTimerRef.current);
262→              flushTimerRef.current = null;
263→            }
264→            flushText();
265→            if (currentTextRef.current.trim()) {
266→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
267→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
268→              currentTextRef.current = '';
269→            }
270→            segmentsRef.current.push({ type: 'error', errorMessage: error });
271→            setMessages((prev) =>
272→              prev.map((m) =>
273→                m.id === assistantId
274→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
275→                  : m
276→              )
277→            );
278→            setIsStreaming(false);
279→            abortRef.current = null;
280→          },
281→          onUserQuestion: (data) => {
282→            if (flushTimerRef.current) {
283→              clearTimeout(flushTimerRef.current);
284→              flushTimerRef.current = null;
285→            }
286→            flushText();
287→            if (currentTextRef.current.trim()) {
288→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
289→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
290→              currentTextRef.current = '';
291→            }
292→            segmentsRef.current.push({
293→              type: 'user_question',
294→              questionData: data,
295→            });
296→            setMessages((prev) =>
297→              prev.map((m) =>
298→                m.id === assistantId
299→                  ? { ...m, segments: [...segmentsRef.current] }
300→                  : m
301→              )
302→            );
303→          },
304→        },
305→        controller.signal,
306→        userSessionId,
307→        skills,
308→      );
309→    },
310→    [isStreaming, flushText, refreshTables, userSessionId]
311→  );
312→
313→  const editMessage = useCallback(
314→    async (messageIndex: number, newContent: string) => {
315→      if (isStreaming) return;
316→
317→      // Build conversation history from messages before the edit point
318→      const conversationHistory: { role: string; content: string }[] = [];
319→      for (let i = 0; i < messageIndex; i++) {
320→        const msg = messages[i];
321→        if (msg.role === 'user' || msg.role === 'assistant') {
322→          conversationHistory.push({ role: msg.role, content: msg.content });
323→        }
324→      }
325→
326→      const assistantId = generateId();
327→      assistantIdRef.current = assistantId;
328→
329→      const userMsg: ChatMessage = {
330→        id: generateId(),
331→        role: 'user',
332→        content: newContent,
333→      };
334→      const assistantMsg: ChatMessage = {
335→        id: assistantId,
336→        role: 'assistant',
337→        content: '',
338→        toolCalls: [],
339→        isStreaming: true,
340→      };
341→
342→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
343→      setIsStreaming(true);
344→      textBufferRef.current = '';
345→      segmentsRef.current = [];
346→      currentTextRef.current = '';
347→      phaseRef.current = 'thinking';
348→
349→      const controller = new AbortController();
350→      abortRef.current = controller;
351→
352→      await runAgentEditLoop(
353→        newContent,
354→        conversationHistory,
355→        generateUUID(),
356→        {
357→          onTextChunk: (chunk) => {
358→            textBufferRef.current += chunk;
359→            if (!flushTimerRef.current) {
360→              flushTimerRef.current = setTimeout(() => {
361→                flushText();
362→                flushTimerRef.current = null;
363→              }, 50);
364→            }
365→          },
366→          onThinkingDone: () => {
367→            if (flushTimerRef.current) {
368→              clearTimeout(flushTimerRef.current);
369→              flushTimerRef.current = null;
370→            }
371→            flushText();
372→            if (currentTextRef.current.trim()) {
373→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
374→              currentTextRef.current = '';
375→            }
376→            phaseRef.current = 'answer';
377→            setMessages((prev) =>
378→              prev.map((m) =>
379→                m.id === assistantId
380→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
381→                  : m
382→              )
383→            );
384→          },
385→          onToolCall: (pending: ToolCallResult) => {
386→            if (flushTimerRef.current) {
387→              clearTimeout(flushTimerRef.current);
388→              flushTimerRef.current = null;
389→            }
390→            flushText();
391→            if (currentTextRef.current.trim()) {
392→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
393→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
394→              currentTextRef.current = '';
395→            }
396→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
397→            setMessages((prev) =>
398→              prev.map((m) =>
399→                m.id === assistantId
400→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
401→                  : m
402→              )
403→            );
404→          },
405→          onToolResult: (result: ToolCallResult) => {
406→            const pendingIdx = segmentsRef.current.findIndex(
407→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
408→            );
409→            if (pendingIdx !== -1) {
410→              const pending = segmentsRef.current[pendingIdx].toolResult!;
411→              segmentsRef.current[pendingIdx] = {
412→                type: 'tool',
413→                toolResult: {
414→                  ...pending,
415→                  ...result,
416→                  sql: result.sql || pending.sql,
417→                  toolName: result.toolName || pending.toolName,
418→                  command: result.command || pending.command,
419→                  toolInput: result.toolInput || pending.toolInput,
420→                },
421→              };
422→            } else {
423→              segmentsRef.current.push({ type: 'tool', toolResult: result });
424→            }
425→            setMessages((prev) =>
426→              prev.map((m) =>
427→                m.id === assistantId
428→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
429→                  : m
430→              )
431→            );
432→            refreshTables();
433→          },
434→          onSubagentStart: (data) => {
435→            if (flushTimerRef.current) {
436→              clearTimeout(flushTimerRef.current);
437→              flushTimerRef.current = null;
438→            }
439→            flushText();
440→            if (currentTextRef.current.trim()) {
441→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
442→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
443→              currentTextRef.current = '';
444→            }
445→            segmentsRef.current.push({
446→              type: 'subagent_start',
447→              subagentId: data.id,
448→              subagentName: data.name,
449→              text: data.prompt,
450→            });
451→            setMessages((prev) =>
452→              prev.map((m) =>
453→                m.id === assistantId
454→                  ? { ...m, segments: [...segmentsRef.current] }
455→                  : m
456→              )
457→            );
458→          },
459→          onSubagentEnd: (data) => {
460→            segmentsRef.current.push({
461→              type: 'subagent_end',
462→              subagentId: data.id,
463→              subagentName: data.name,
464→              chart_spec: data.chart_spec,
465→              sqlResults: data.sql_results,
466→              text: data.result,
467→            });
468→            setMessages((prev) =>
469→              prev.map((m) =>
470→                m.id === assistantId
471→                  ? { ...m, segments: [...segmentsRef.current] }
472→                  : m
473→              )
474→            );
475→          },
476→          onDone: (newSessionId) => {
477→            if (newSessionId) sessionIdRef.current = newSessionId;
478→            if (flushTimerRef.current) {
479→              clearTimeout(flushTimerRef.current);
480→              flushTimerRef.current = null;
481→            }
482→            flushText();
483→            if (currentTextRef.current.trim()) {
484→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
485→              currentTextRef.current = '';
486→            }
487→            setMessages((prev) =>
488→              prev.map((m) =>
489→                m.id === assistantId
490→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
491→                  : m
492→              )
493→            );
494→            setIsStreaming(false);
495→            abortRef.current = null;
496→          },
497→          onError: (error) => {
498→            if (flushTimerRef.current) {
499→              clearTimeout(flushTimerRef.current);
500→              flushTimerRef.current = null;
501→            }
502→            flushText();
503→            if (currentTextRef.current.trim()) {
504→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
505→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
506→              currentTextRef.current = '';
507→            }
508→            segmentsRef.current.push({ type: 'error', errorMessage: error });
509→            setMessages((prev) =>
510→              prev.map((m) =>
511→                m.id === assistantId
512→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
513→                  : m
514→              )
515→            );
516→            setIsStreaming(false);
517→            abortRef.current = null;
518→          },
519→          onUserQuestion: (data) => {
520→            if (flushTimerRef.current) {
521→              clearTimeout(flushTimerRef.current);
522→              flushTimerRef.current = null;
523→            }
524→            flushText();
525→            if (currentTextRef.current.trim()) {
526→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
527→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
528→              currentTextRef.current = '';
529→            }
530→            segmentsRef.current.push({
531→              type: 'user_question',
532→              questionData: data,
533→            });
534→            setMessages((prev) =>
535→              prev.map((m) =>
536→                m.id === assistantId
537→                  ? { ...m, segments: [...segmentsRef.current] }
538→                  : m
539→              )
540→            );
541→          },
542→        },
543→        controller.signal,
544→        userSessionId,
545→      );
546→    },
547→    [isStreaming, messages, flushText, refreshTables, userSessionId]
548→  );
549→
550→  const deleteMessage = useCallback(
551→    (messageIndex: number) => {
552→      if (isStreaming) return;
553→
554→      // Store remaining messages as history for Langfuse context on next send
555→      setMessages((prev) => {
556→        const remaining = prev.slice(0, messageIndex);
557→        pendingHistoryRef.current = remaining
558→          .filter((m) => m.role === 'user' || m.role === 'assistant')
559→          .map((m) => ({ role: m.role, content: m.content }));
560→        return remaining;
561→      });
562→
563→      // Clear session so next message starts fresh
564→      sessionIdRef.current = null;
565→    },
566→    [isStreaming]
567→  );
568→
569→  const respondToQuestion = useCallback(
570→    async (questionId: string, answers: string[], freeText?: string) => {
571→      // Update the segment to show the user's answer
572→      const segIdx = segmentsRef.current.findIndex(
573→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
574→      );
575→      if (segIdx !== -1) {
576→        segmentsRef.current[segIdx] = {
577→          ...segmentsRef.current[segIdx],
578→          userAnswer: answers,
579→          userFreeText: freeText,
580→        };
581→        setMessages((prev) =>
582→          prev.map((m) =>
583→            m.id === assistantIdRef.current
584→              ? { ...m, segments: [...segmentsRef.current] }
585→              : m
586→          )
587→        );
588→      }
589→
590→      // POST to backend
591→      try {
592→        await fetch('/api/chat/respond', {
593→          method: 'POST',
594→          headers: {
595→            'Content-Type': 'application/json',
596→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
597→          },
598→          body: JSON.stringify({
599→            question_id: questionId,
600→            answers,
601→            free_text: freeText || null,
602→          }),
603→        });
604→      } catch (e) {
605→        console.error('Failed to respond to question:', e);
606→      }
607→    },
608→    [userSessionId]
609→  );
610→
611→  const clearMessages = useCallback(() => {
612→    if (abortRef.current) {
613→      abortRef.current.abort();
614→    }
615→    setMessages([]);
616→    setIsStreaming(false);
617→    sessionIdRef.current = null;
618→    pendingHistoryRef.current = null;
619→  }, []);
620→
621→  return (
622→    <AgentContext.Provider
623→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
624→    >
625→      {children}
626→    </AgentContext.Provider>
627→  );
628→}
