  1→import { createContext, useState, useCallback, useContext, ReactNode } from 'react';
  2→import type { ChatMessage } from '../types';
  3→import { buildChatMessages } from '../utils/buildChatMessages';
  4→
  5→interface Conversation {
  6→  id: string;
  7→  title: string | null;
  8→  created_at: string;
  9→  updated_at: string;
 10→  messages?: Array<{
 11→    id: string;
 12→    role: string;
 13→    content: string;
 14→    metadata: string | null;
 15→    sort_order: number;
 16→  }>;
 17→}
 18→
 19→interface ConversationContextType {
 20→  activeConversationId: string | null;
 21→  refreshTrigger: number;
 22→  createConversation: (firstMessage: string) => Promise<string>;
 23→  selectConversation: (id: string) => Promise<ChatMessage[]>;
 24→  deleteConversation: (id: string) => Promise<void>;
 25→  renameConversation: (id: string, title: string) => Promise<void>;
 26→  startNewConversation: () => void;
 27→  triggerRefresh: () => void;
 28→}
 29→
 30→const ConversationContext = createContext<ConversationContextType | null>(null);
 31→
 32→export function ConversationProvider({ children, sessionId }: { children: ReactNode; sessionId: string }) {
 33→  const [activeConversationId, setActiveConversationId] = useState<string | null>(null);
 34→  const [refreshTrigger, setRefreshTrigger] = useState(0);
 35→
 36→  const triggerRefresh = useCallback(() => {
 37→    setRefreshTrigger((n) => n + 1);
 38→  }, []);
 39→
 40→  const createConversation = useCallback(async (firstMessage: string): Promise<string> => {
 41→    const title = firstMessage.length > 50 ? firstMessage.slice(0, 50) + '...' : firstMessage;
 42→    const res = await fetch('/api/conversations', {
 43→      method: 'POST',
 44→      headers: { 'Content-Type': 'application/json', 'X-Session-ID': sessionId },
 45→      body: JSON.stringify({ title }),
 46→    });
 47→    const conv = await res.json();
 48→    setActiveConversationId(conv.id);
 49→    triggerRefresh();
 50→    return conv.id;
 51→  }, [triggerRefresh, sessionId]);
 52→
 53→  const selectConversation = useCallback(async (id: string): Promise<ChatMessage[]> => {
 54→    console.log('[CONV-DEBUG] selectConversation fetching', { id, currentActiveId: activeConversationId });
 55→    const res = await fetch(`/api/conversations/${id}`);
 56→    if (!res.ok) throw new Error('Failed to load conversation');
 57→    const conv: Conversation = await res.json();
 58→    console.log('[CONV-DEBUG] selectConversation response', { id, messageCount: conv.messages?.length, messages: conv.messages?.map(m => ({ id: m.id.slice(0,8), role: m.role, contentLen: m.content.length, hasMeta: !!m.metadata })) });
 59→    setActiveConversationId(id);
 60→
 61→    return buildChatMessages(conv.messages || []);
 62→  }, []);
 63→
 64→  const deleteConversation = useCallback(async (id: string) => {
 65→    await fetch(`/api/conversations/${id}`, { method: 'DELETE' });
 66→    if (activeConversationId === id) {
 67→      setActiveConversationId(null);
 68→    }
 69→    triggerRefresh();
 70→  }, [activeConversationId, triggerRefresh]);
 71→
 72→  const renameConversation = useCallback(async (id: string, title: string) => {
 73→    await fetch(`/api/conversations/${id}`, {
 74→      method: 'PUT',
 75→      headers: { 'Content-Type': 'application/json' },
 76→      body: JSON.stringify({ title }),
 77→    });
 78→    triggerRefresh();
 79→  }, [triggerRefresh]);
 80→
 81→  const startNewConversation = useCallback(() => {
 82→    setActiveConversationId(null);
 83→  }, []);
 84→
 85→  return (
 86→    <ConversationContext.Provider
 87→      value={{
 88→        activeConversationId,
 89→        refreshTrigger,
 90→        createConversation,
 91→        selectConversation,
 92→        deleteConversation,
 93→        renameConversation,
 94→        startNewConversation,
 95→        triggerRefresh,
 96→      }}
 97→    >
 98→      {children}
 99→    </ConversationContext.Provider>
100→  );
101→}
102→
103→export function useConversation() {
104→  const ctx = useContext(ConversationContext);
105→  if (!ctx) throw new Error('useConversation must be used within ConversationProvider');
106→  return ctx;
107→}
