379→export default function App() {
380→  const sessionId = useSessionId();
381→  const [tables, setTables] = useState<TableInfo[]>([]);
382→  const [loading, setLoading] = useState(true);
383→  const [error, setError] = useState<string | null>(null);
384→  const refreshTables = useCallback(async () => {
385→    try {
386→      const response = await fetch('/api/tables', {
387→        headers: { 'X-Session-ID': sessionId },
388→      });
389→      if (!response.ok) throw new Error('Failed to fetch tables');
390→      const data = await response.json();
391→      setTables(data);
392→    } catch (e) {
393→      console.error('Failed to refresh tables:', e);
394→    }
395→  }, [sessionId]);
396→
397→  useEffect(() => {
398→    (async () => {
399→      try {
400→        const response = await fetch('/api/health');
401→        if (!response.ok) throw new Error('Backend is not available');
402→        await refreshTables();
403→      } catch (e) {
404→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
405→      } finally {
406→        setLoading(false);
407→      }
408→    })();
409→  }, [refreshTables]);
410→
411→  if (loading) {
412→    return <div className="app-loading">Connecting to backend...</div>;
413→  }
414→
415→  if (error) {
416→    return (
417→      <div className="app-error">Failed to connect: {error}</div>
418→    );
419→  }
420→
421→  return (
422→    <ConfigProvider>
423→      <LanguageProvider>
424→        <ThemeProvider>
425→          <ConversationProvider sessionId={sessionId}>
426→            <AgentProvider refreshTables={refreshTables}>
427→              <AppContent tables={tables} refreshTables={refreshTables} sessionId={sessionId} />
428→            </AgentProvider>
429→          </ConversationProvider>
430→        </ThemeProvider>
431→      </LanguageProvider>
432→    </ConfigProvider>
433→  );
434→}
