 74→      const userMsg: ChatMessage = {
 75→        id: generateId(),
 76→        role: 'user',
 77→        content: text,
 78→      };
 79→
 80→      const assistantId = generateId();
 81→      assistantIdRef.current = assistantId;
 82→      const assistantMsg: ChatMessage = {
 83→        id: assistantId,
 84→        role: 'assistant',
 85→        content: '',
 86→        toolCalls: [],
 87→        isStreaming: true,
 88→      };
 89→
 90→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 91→      setIsStreaming(true);
 92→      textBufferRef.current = '';
 93→      segmentsRef.current = [];
 94→      currentTextRef.current = '';
 95→      phaseRef.current = 'thinking';
 96→
 97→      // Build conversation history from current messages for resume fallback.
 98→      // Read from messagesRef (not the stale closure `messages`) so that
 99→      // switching conversations is reflected immediately.
100→      const history = messagesRef.current
101→        .filter((m) => m.role === 'user' || m.role === 'assistant')
102→        .map((m) => ({ role: m.role, content: m.content }));
103→
104→      // If there's pending history from a delete, start a new Langfuse session with that context
105→      const pendingHistory = pendingHistoryRef.current;
106→      pendingHistoryRef.current = null;
107→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
108→
109→      const controller = new AbortController();
110→      abortRef.current = controller;
111→
112→      // Extract all /skill-name references from message
113→      let actualMessage = text;
114→      let skills: string[] | undefined;
115→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
116→      if (slashMatches.length > 0) {
