118→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
119→      }
120→
121→      await runAgentLoop(
122→        actualMessage,
123→        sessionIdRef.current,
124→        langfuseSessionId,
125→        pendingHistory ?? (history.length > 0 ? history : null),
126→        conversationId,
127→        {
128→          onTextChunk: (chunk) => {
129→            if (streamGenerationRef.current !== generation) return;
130→            textBufferRef.current += chunk;
131→            if (!flushTimerRef.current) {
132→              flushTimerRef.current = setTimeout(() => {
133→                flushText();
134→                flushTimerRef.current = null;
135→              }, 50);
136→            }
137→          },
138→          onThinkingDone: () => {
139→            if (streamGenerationRef.current !== generation) return;
140→            // Extended thinking just ended and a text block is starting.
141→            // Create a thinking segment from accumulated thinking text.
142→            if (flushTimerRef.current) {
143→              clearTimeout(flushTimerRef.current);
144→              flushTimerRef.current = null;
145→            }
146→            flushText();
147→            if (currentTextRef.current.trim()) {
148→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
149→              currentTextRef.current = '';
150→            }
151→            phaseRef.current = 'answer';
152→            setMessages((prev) =>
153→              prev.map((m) =>
154→                m.id === assistantId
155→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
156→                  : m
157→              )
158→            );
159→          },
160→          onToolCall: (pending: ToolCallResult) => {
161→            if (streamGenerationRef.current !== generation) return;
162→            if (flushTimerRef.current) {
163→              clearTimeout(flushTimerRef.current);
164→              flushTimerRef.current = null;
165→            }
166→            flushText();
167→            if (currentTextRef.current.trim()) {
168→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
169→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
170→              currentTextRef.current = '';
171→            }
172→            // Add a pending tool segment so the input is shown immediately
173→            segmentsRef.current.push({
174→              type: 'tool',
175→              toolResult: pending,
176→            });
177→            setMessages((prev) =>
178→              prev.map((m) =>
179→                m.id === assistantId
180→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
181→                  : m
182→              )
183→            );
184→          },
185→          onToolResult: (result: ToolCallResult) => {
186→            if (streamGenerationRef.current !== generation) return;
