190→            );
191→            if (pendingIdx !== -1) {
192→              const pending = segmentsRef.current[pendingIdx].toolResult!;
193→              segmentsRef.current[pendingIdx] = {
194→                type: 'tool',
195→                toolResult: {
196→                  ...pending,
197→                  ...result,
198→                  sql: result.sql || pending.sql,
199→                  toolName: result.toolName || pending.toolName,
200→                  command: result.command || pending.command,

700→          )
