 48→    const trimmed = text.trim();
 49→    console.log('[CONV-DEBUG] ChatInput handleSend', { trimmed: trimmed.slice(0, 30), isStreaming, activeConversationId });
 50→    if (!trimmed || isStreaming) return;
 51→    setText('');
 52→    setShowSlashMenu(false);
 53→    if (textareaRef.current) {
 54→      textareaRef.current.style.height = 'auto';
 55→    }
 56→
 57→    let convId = activeConversationId;
 58→    if (!convId) {
 59→      console.log('[CONV-DEBUG] ChatInput creating conversation');
 60→      convId = await createConversation(trimmed);
 61→      console.log('[CONV-DEBUG] ChatInput conversation created', { convId });
 62→    }
 63→    console.log('[CONV-DEBUG] ChatInput calling sendMessage', { convId });
 64→    await sendMessage(trimmed, convId);
